#include <iostream>
#include <string>
using namespace std;

int main() {
    string s;
    getline(cin, s);
    int kiri = 0, kanan = (int) s.size() - 1;
    bool palindrom = true;
    while (kiri < kanan) {
        if (s[kiri] == ' ') {
            kiri++;
            continue;
        }
        if (s[kanan] == ' ') {
            kanan--;
            continue;
        }
        char a = s[kiri], b = s[kanan];
        if (a >= 'A' && a <= 'Z') a = a - 'A' + 'a';
        if (b >= 'A' && b <= 'Z') b = b - 'A' + 'a';
        if (a != b) {
            palindrom = false;
            break;
        }
        kiri++;
        kanan--;
    }
    if (palindrom) {
        cout << "palindrom" << endl;
    } else {
        cout << "bukan palindrom" << endl;
    }
    return 0;
}

