#include <iostream>
#include <string>
using namespace std;

int main() {
    int saldo;
    cin >> saldo;
    int ditolak = 0, beruntun = 0;
    bool diblokir = false;
    string perintah;
    while (cin >> perintah) {
        if (perintah == "selesai") {
            break;
        }
        int jumlah;
        cin >> jumlah;
        if (perintah == "setor") {
            saldo += jumlah;
            beruntun = 0;
        } else if (jumlah % 50000 != 0 || jumlah > saldo) {
            ditolak++;
            beruntun++;
            if (beruntun == 3) {
                diblokir = true;
                break;
            }
        } else {
            saldo -= jumlah;
            beruntun = 0;
        }
    }
    cout << "Saldo akhir: " << saldo << endl;
    cout << "Ditolak: " << ditolak << endl;
    if (diblokir) {
        cout << "Status: diblokir" << endl;
    } else {
        cout << "Status: normal" << endl;
    }
    return 0;
}

